  'Aplicam-se a todas as execuções desta subnet, manuais e agendadas. Cada ping ou ligação TCP conta como uma sonda. Vazio usa o valor predefinido (em cinzento).': 'Elles s’appliquent à toutes les exécutions de ce sous-réseau, manuelles et planifiées. Chaque ping ou connexion TCP compte comme une sonde. Vide : la valeur par défaut (en gris) est utilisée.',
