  'Traps de IPs que não foram pré-registados aparecem no SNMP, em Traps de equipamentos desconhecidos.': 'Les traps provenant d’IP non pré-enregistrées apparaissent dans SNMP, sous Traps d’équipements inconnus.',
  'SNMP → Traps de equipamentos desconhecidos': 'SNMP → Traps d’équipements inconnus',
  'Para equipamentos SNMP, usa o separador SNMP. Pré-registar um equipamento é dizer à app, antes de ele estar no inventário, de que IP vão chegar as traps e com que credenciais. O pré-registo dura 24 horas e associa as traps que chegarem desse IP. Traps de IPs não pré-registados não se perdem:': 'Pour les équipements SNMP, utilisez l’onglet SNMP. Pré-enregistrer un équipement consiste à indiquer à l’application, avant qu’il ne figure dans l’inventaire, de quelle IP proviendront ses traps et avec quels identifiants. Le pré-enregistrement dure 24 heures et associe les traps qui arrivent de cette IP. Les traps provenant d’IP non pré-enregistrées ne sont pas perdus :',
